import{z as o,x as n,o as B,c as s,q as e,j as t,D as a,d as l,s as r,S as i}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"自动稳定器","description":"","frontmatter":{"title":"自动稳定器","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/automatic-stabilizers.md","filePath":"econ/automatic-stabilizers.md","lastUpdated":1791063341000}'),p={name:"econ/automatic-stabilizers.md"};function d(_,E,c,D,m,h){const A=n("Mermaid");return B(),s("div",null,[E[2]||(E[2]=e('<h1 id="自动稳定器" tabindex="-1">自动稳定器 <a class="header-anchor" href="#自动稳定器" aria-label="Permalink to &quot;自动稳定器&quot;">​</a></h1><div class="epigraph"><p>累进税与失业保险让盈余在产出下降时自动变弱，不必再通过一次立法；这是财政规则里的反馈，不是又一次相机 $G$。</p><footer>—— 据 Blinder and Solow 对财政政策是否「有用」的讨论；税制累进把弹性写进预算</footer></div><p><a href="/econ/ftpl">上一课</a>把名义债的实际值接到初级盈余现值，并区分财政主动与被动。本课的缺口是：许多盈余反馈<strong>无需新立法</strong>——税率累进、失业给付、公司利润税——使 \\(T-G\\) 随 \\(Y\\) 自动动。开放经济会计从下一课起把 \\(S-I\\) 接到经常账户；本课先把国内预算的自动部分钉住。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>乘数课的 \\(G\\) 是相机购买；FTPL 的主动财政是盈余过程不对债务作充分反应。中间还有第三种对象：立法已写好的弹性。产出下降时，累进所得税使平均税率下降，失业保险使转移上升，初级盈余恶化。这不是「又一次刺激法案」，是规则。缺口是：自动稳定器如何进入已经学过的 IS、李嘉图与 Leeper 的被动财政，而不把它们重写成政治口号。</p><p><span class="marginnote">「自动稳定器」就是「不用再开一次会就自动生效的财政刹车与油门」：经济降温时税收自动少收、补助自动多发。可以把它想象成汽车的减震器——它不改变发动机的功率，只是让颠簸被吸收掉一部分。</span></p><p>FTPL 要的是盈余对债务（或对 \\(P\\)）是否调整。稳定器提供的是对 \\(Y\\) 的弹性，有助于被动，但立法仍可以同时规定债务上升也不加税。本课把「无需新立法」钉住，开放课序从下一课才把 \\(S-I\\) 接到 \\(CA\\)。</p><p><span class="marginnote">自动稳定器改变的是盈余对 \\(Y\\)（和债务）的弹性。弹性足够大，财政更接近 Leeper 意义上的被动：债务上升之后，无需新决议也会有一部分盈余跟上。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把税收写成 \\(T_t=T(Y_t)\\)，\\(T&#39;\\gt 0\\) 且累进时平均税率随 \\(Y\\) 升。失业给付是反向的转移。Blinder 与 Solow 问财政是否「有用」时，已经把预算内生进 IS–LM：盈余随 \\(Y\\) 改善，对债务累积有刹车。欧拉与李嘉图下，一次总付的自动转移仍可能被未来税抵消；扭曲税与流动性约束让当期可支配收入通道复活。NK 里，自动稳定器改变的是缺口对需求冲击的映射：同样的 \\(G\\) 或外生需求下降，可支配收入少掉一截，乘数更小。</p>',10)),(B(),t(i,null,{default:a(()=>[r(A,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20Y%5B%22%E4%BA%A7%E5%87%BA%E4%B8%8B%E9%99%8D%22%5D%20--%3E%20TAX%5B%22%E7%B4%AF%E8%BF%9B%E7%A8%8E%EF%BC%9AT%20%E9%99%8D%22%5D%0A%20%20Y%20--%3E%20UI%5B%22%E5%A4%B1%E4%B8%9A%E7%BB%99%E4%BB%98%EF%BC%9A%E8%BD%AC%E7%A7%BB%E5%8D%87%22%5D%0A%20%20TAX%20--%3E%20S%5B%22%E5%88%9D%E7%BA%A7%E7%9B%88%E4%BD%99%E8%87%AA%E5%8A%A8%E6%81%B6%E5%8C%96%22%5D%0A%20%20UI%20--%3E%20S%0A%20%20S%20--%3E%20BUF%5B%22%E7%BC%93%E5%86%B2%E7%BC%BA%E5%8F%A3%EF%BC%8C%E6%97%A0%E9%9C%80%E6%96%B0%E6%B3%95%22%5D%0A%20%20S%20--%3E%20PAS%5B%22%E9%9D%A0%E8%BF%91%E8%B4%A2%E6%94%BF%E8%A2%AB%E5%8A%A8%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[l(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e('<p>下限上，相机 \\(G\\) 的乘数往往更大；自动稳定器仍然工作，而且不依赖议会再开一次会——这是执行时滞的差，不是另一套乘数公式。卢卡斯批判：稳定器的弹性是税法的结构，用旧税法样本去模拟「若累进更陡」必须重解，不能平移 MPC。</p><h3 id="与相机财政、与-ftpl" tabindex="-1">与相机财政、与 FTPL <a class="header-anchor" href="#与相机财政、与-ftpl" aria-label="Permalink to &quot;与相机财政、与 FTPL&quot;">​</a></h3><p>相机财政是新立法：\\(G\\) 或税率表本身改变。自动稳定器是给定税法下的反馈。FTPL 关心的是盈余现值是否钉住 \\(P\\)；稳定器提供一条对 \\(Y\\) 从而对税基的反馈，有助于被动，但若立法同时规定「债务上升也不加税、不减支」，主动仍可成立。二者不要并成「有失业保险就不会通胀」。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>需求下降 → \\(Y\\) 降 → 税基缩小、给付扩大 → 私人可支配收入少降一截 → 欧拉上受约束家庭的 \\(C\\) 少降 → 缺口比没有稳定器时更浅。反向过热时自动紧缩。长期中性：\\(y^*\\) 仍由实物决定，稳定器不永久改变自然产出；它们改变的是名义需求冲击下 \\(\\tilde{y}\\) 的振幅。铸币税仍是盈余的一项；稳定器主要走所得税与转移，不是印钞。</p><p><span class="marginnote">数字实例：设年收入超过 5 万的部分按 20% 征税。收入从 8 万跌到 6 万（跌 25%），税款从 6000 降到 2000，可支配收入只从 74000 跌到 58000（跌约 22%）——免税额与累进结构自动替家庭吸收了 4000 的冲击，比例税则一分钱都不吸收。</span></p>',6)),(B(),t(i,null,{default:a(()=>[r(A,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20SH%5B%22%E5%90%8C%E6%A0%B7%E7%9A%84%E8%B4%9F%E9%9C%80%E6%B1%82%E5%86%B2%E5%87%BB%22%5D%20--%3E%20A%5B%22%E6%97%A0%E7%A8%B3%E5%AE%9A%E5%99%A8%E8%B7%AF%E5%BE%84%22%5D%0A%20%20SH%20--%3E%20B%5B%22%E6%9C%89%E7%A8%B3%E5%AE%9A%E5%99%A8%E8%B7%AF%E5%BE%84%22%5D%0A%20%20A%20--%3E%20A2%5B%22%E7%A8%8E%E5%9F%BA%E7%BC%A9%E5%B0%8F%EF%BC%8C%E7%BB%99%E4%BB%98%E4%B8%8D%E5%8F%98%22%5D%0A%20%20A2%20--%3E%20A3%5B%22%E5%8F%AF%E6%94%AF%E9%85%8D%E6%94%B6%E5%85%A5%E5%85%A8%E9%A2%9D%E4%B8%8B%E9%99%8D%22%5D%0A%20%20A3%20--%3E%20A4%5B%22%E4%BA%A7%E5%87%BA%E7%BC%BA%E5%8F%A3%E6%9B%B4%E6%B7%B1%22%5D%0A%20%20B%20--%3E%20B2%5B%22%E7%B4%AF%E8%BF%9B%E7%A8%8E%E5%B0%91%E6%94%B6%EF%BC%8C%E7%BB%99%E4%BB%98%E5%A4%9A%E4%BB%98%22%5D%0A%20%20B2%20--%3E%20B3%5B%22%E5%8F%AF%E6%94%AF%E9%85%8D%E6%94%B6%E5%85%A5%E5%B0%91%E9%99%8D%E4%B8%80%E6%88%AA%22%5D%0A%20%20B3%20--%3E%20B4%5B%22%E4%BA%A7%E5%87%BA%E7%BC%BA%E5%8F%A3%E6%9B%B4%E6%B5%85%22%5D%0A%20%20A4%20--%3E%20C%5B%22%E4%B8%A4%E6%9D%A1%E8%B7%AF%E5%BE%84%E7%9A%84%E6%8C%AF%E5%B9%85%E5%B7%AE%E5%B0%B1%E6%98%AF%E7%A8%B3%E5%AE%9A%E5%99%A8%E7%9A%84%E4%BD%9C%E7%94%A8%22%5D%0A%20%20B4%20--%3E%20C%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[l(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=e('<p>时间不一致：把自动稳定器临时关掉（「今年暂停失业金」）是再优化，预期会对准将来也会停。承诺技术包括把弹性写进税法而不是写进年度预算演讲。乘数课的李嘉图在一次总付转移上最强；失业给付针对受约束家庭，MPC 更高，缓冲才不是会计上的零。Blinder–Solow 在 IS–LM 里已经让预算内生；欧拉下同样的弹性改的是哪一类家庭的现金流，而不是把 \\(C=cY\\) 请回结构。</p><p><span class="marginnote">公司利润税、累进个人所得税、按通胀指数化的税档，弹性不同。本课不估某个国家的「半弹性」。指数化税档会削弱通胀对实际税负的自动抬升。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把稳定器写成最优税率表，不估计「失业保险永远乘数 0.x」。开放漏出与下课经常账户会改变封闭缓冲。公司金融的税盾不是宏观自动稳定器。量化栏没有财政。累进也可以来自定额免税额：名义收入下降时更多家庭掉进免税，弹性不必写成连续边际税率。指数化税档则削弱「通胀自动加税」那一条，与稳定器的方向可以相反，要分开声明。</p><p>突然停止时稳定器让 \\(S^g\\) 下降，会加大需要私人调整或贬值的幅度——开放约束与国内缓冲可以打架。那不是否定稳定器，是声明国境已经打开之后的课序。本课先封闭。</p><p><span class="marginnote">常见误区：把自动稳定器当成「又一轮刺激」。刺激要新立法、改税率或支出计划；稳定器什么都不改，只是让既有规则随产出摆动。反过来，若在衰退中临时收紧失业金来压赤字，等于亲手拆掉减震器，缺口会被放大。</span></p><p>后课默认：谈财政规则时，先分相机立法与已写入税法的弹性。下一课打开国境：国民储蓄与投资的差是经常账户。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>自动稳定器是无需新立法的盈余反馈，核心是累进税与失业给付。</li><li>它们缓冲缺口，并帮助财政靠近 Leeper 的被动。</li><li>不是相机 \\(G\\)，也不是「有稳定器则无 FTPL」。</li><li>弹性是税法结构；跨规则模拟要重解。</li><li>受约束家庭上缓冲才不是李嘉图会计零。</li><li>出处：Blinder and Solow 对财政政策的讨论；税制累进。</li></ul>',9))])}const T=o(p,[["render",d]]);export{F as __pageData,T as default};
